// Generated by scripts/gen-workflow-templates.mjs from .github-templates. Do not edit; run npm run gen:workflows.

/** The GitHub Actions templates as strings (M144), keyed by the workflow name the download route takes. */
export const WORKFLOW_TEMPLATES = {
  sync: "# CanHav GitHub sync (Studio+). Download it filled in from the project page\n# (Deployments, GitHub setup), or copy this file to\n# .github/workflows/canhav-sync.yml in your repository. On every push and pull request it reads the Foundry\n# broadcast files for your project's chain, sends the deployed contracts\n# to Deployments, and ticks build steps named in commit messages or the PR\n# body as \"canhav: <stepId>\" lines. Needs one secret, CANHAV_PROJECT_KEY,\n# a write key from the project page (Deployments, Project keys). The\n# downloaded file carries the chain id and the CanHav address; this copy\n# reads them from the variables CANHAV_CHAIN_ID (46630 for Robinhood Chain\n# testnet, 421614 for Arbitrum Sepolia) and CANHAV_URL. Writes ride the project's agent write mode, so in\n# propose mode they wait for the owner in the studio.\nname: CanHav sync\non:\n  push:\n    branches: [\"**\"]\n  pull_request:\njobs:\n  sync:\n    runs-on: ubuntu-latest\n    permissions:\n      contents: read\n      pull-requests: read\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 2\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n      - name: Send deployments and steps to CanHav\n        env:\n          CANHAV_PROJECT_KEY: ${{ secrets.CANHAV_PROJECT_KEY }}\n          CANHAV_CHAIN_ID: ${{ vars.CANHAV_CHAIN_ID }}\n          CANHAV_URL: ${{ vars.CANHAV_URL || 'https://www.canhav.com' }}\n          COMMIT_SHA: ${{ github.sha }}\n          COMMIT_URL: ${{ github.server_url }}/${{ github.repository }}/commit/${{ github.sha }}\n          COMMIT_MESSAGE: ${{ github.event.head_commit.message || github.event.pull_request.title }}\n          PR_NUMBER: ${{ github.event.pull_request.number }}\n          PR_URL: ${{ github.event.pull_request.html_url }}\n          PR_TITLE: ${{ github.event.pull_request.title }}\n          PR_BODY: ${{ github.event.pull_request.body }}\n        run: |\n          node - <<'JS'\n          const fs = require(\"fs\");\n          const path = require(\"path\");\n          const chainId = Number(process.env.CANHAV_CHAIN_ID);\n          if (!process.env.CANHAV_PROJECT_KEY || !chainId) { console.log(\"CANHAV_PROJECT_KEY or CANHAV_CHAIN_ID missing, skipping.\"); process.exit(0); }\n          const broadcasts = [];\n          const walk = (dir) => {\n            if (!fs.existsSync(dir)) return;\n            for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n              const p = path.join(dir, e.name);\n              if (e.isDirectory()) { if (e.name === \"node_modules\" || e.name.startsWith(\".\")) continue; walk(p); }\n              else if (e.name === \"run-latest.json\" && p.includes(`${path.sep}${chainId}${path.sep}`)) {\n                try {\n                  const j = JSON.parse(fs.readFileSync(p, \"utf8\"));\n                  const script = path.basename(path.dirname(path.dirname(p)));\n                  const contracts = (j.transactions || []).filter((t) => t.transactionType === \"CREATE\" && t.contractAddress).map((t) => ({ name: t.contractName || \"Contract\", address: String(t.contractAddress).toLowerCase() }));\n                  if (contracts.length) broadcasts.push({ script, chainId, contracts });\n                } catch (err) { console.log(\"skip\", p, String(err)); }\n              }\n            }\n          };\n          walk(process.cwd());\n          const text = `${process.env.COMMIT_MESSAGE || \"\"}\\n${process.env.PR_BODY || \"\"}`;\n          const steps = [...new Set([...text.matchAll(/^\\s*canhav:\\s*([a-z0-9_.-]+)\\s*$/gim)].map((m) => m[1]))].map((id) => ({ id }));\n          const payload = {\n            commit: { sha: process.env.COMMIT_SHA, url: process.env.COMMIT_URL, message: (process.env.COMMIT_MESSAGE || \"\").slice(0, 400) },\n            pr: process.env.PR_NUMBER ? { number: Number(process.env.PR_NUMBER), url: process.env.PR_URL, title: (process.env.PR_TITLE || \"\").slice(0, 200) } : null,\n            broadcasts,\n            steps,\n          };\n          if (!broadcasts.length && !steps.length) { console.log(\"Nothing to sync.\"); process.exit(0); }\n          fetch(`${process.env.CANHAV_URL}/api/sync/github`, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${process.env.CANHAV_PROJECT_KEY}` },\n            body: JSON.stringify(payload),\n          }).then(async (r) => { console.log(r.status, await r.text()); if (!r.ok) process.exit(1); });\n          JS\n", // copy-ok, generated YAML
  checks: "# CanHav checks (Studio+). Download it filled in from the project page\n# (Deployments, GitHub setup), or copy this file to\n# .github/workflows/canhav-checks.yml. On every push it runs Slither on the Foundry project, asks Sourcify whether\n# the deployed addresses in the broadcast files are verified, and posts one\n# run per tool to CanHav, where the Review milestone shows the result as\n# proof beside the team's own verdict. Needs the secret CANHAV_PROJECT_KEY\n# (a write key); the downloaded file carries the chain id and the CanHav\n# address, this copy reads the variables CANHAV_CHAIN_ID and CANHAV_URL.\n# Set the variable CANHAV_ADERYN to 1 to run Aderyn instead of Slither.\nname: CanHav checks\non:\n  push:\n    branches: [\"**\"]\njobs:\n  checks:\n    runs-on: ubuntu-latest\n    permissions:\n      contents: read\n    env:\n      CANHAV_PROJECT_KEY: ${{ secrets.CANHAV_PROJECT_KEY }}\n      CANHAV_CHAIN_ID: ${{ vars.CANHAV_CHAIN_ID }}\n      CANHAV_URL: ${{ vars.CANHAV_URL || 'https://www.canhav.com' }}\n      RUN_URL: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          submodules: recursive\n      - uses: foundry-rs/foundry-toolchain@v1\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n      - name: Slither\n        if: ${{ vars.CANHAV_ADERYN != '1' }}\n        uses: crytic/slither-action@v0.4.1\n        continue-on-error: true\n        with:\n          target: .\n          slither-args: --json slither.json --exclude-dependencies\n          fail-on: none\n      - name: Aderyn\n        if: ${{ vars.CANHAV_ADERYN == '1' }}\n        continue-on-error: true\n        run: |\n          curl -L https://raw.githubusercontent.com/Cyfrin/aderyn/dev/cyfrinup/install | bash\n          export PATH=\"$HOME/.cyfrin/bin:$PATH\"\n          cyfrinup && aderyn . -o aderyn.json\n      - name: Post the runs to CanHav\n        run: |\n          node - <<'JS'\n          const fs = require(\"fs\");\n          const path = require(\"path\");\n          const chainId = Number(process.env.CANHAV_CHAIN_ID);\n          if (!process.env.CANHAV_PROJECT_KEY || !chainId) { console.log(\"CANHAV_PROJECT_KEY or CANHAV_CHAIN_ID missing, skipping.\"); process.exit(0); }\n          const sha = process.env.GITHUB_SHA;\n          const post = async (body) => {\n            const r = await fetch(`${process.env.CANHAV_URL}/api/checks`, { method: \"POST\", headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${process.env.CANHAV_PROJECT_KEY}` }, body: JSON.stringify(body) });\n            console.log(body.tool, r.status, await r.text());\n          };\n          const sev = (s) => ({ high: \"high\", medium: \"medium\", low: \"low\" }[String(s || \"\").toLowerCase()] || \"informational\");\n          const count = (findings) => findings.reduce((c, f) => { c[f.severity] += 1; return c; }, { high: 0, medium: 0, low: 0, informational: 0 });\n          (async () => {\n            if (fs.existsSync(\"slither.json\")) {\n              const j = JSON.parse(fs.readFileSync(\"slither.json\", \"utf8\"));\n              const dets = (j.results && j.results.detectors) || [];\n              const findings = dets.map((d) => ({ title: String(d.check || d.description || \"\").slice(0, 160), severity: sev(d.impact), file: (d.elements && d.elements[0] && d.elements[0].source_mapping && d.elements[0].source_mapping.filename_short || \"\").slice(0, 200) })).slice(0, 20);\n              const counts = count(dets.map((d) => ({ severity: sev(d.impact) })));\n              await post({ tool: \"slither\", commitSha: sha, runUrl: process.env.RUN_URL, result: counts.high > 0 ? \"fail\" : \"pass\", summary: { counts, findings } });\n            } else if (fs.existsSync(\"aderyn.json\")) {\n              const j = JSON.parse(fs.readFileSync(\"aderyn.json\", \"utf8\"));\n              const high = (j.high_issues && j.high_issues.issues) || [];\n              const low = (j.low_issues && j.low_issues.issues) || [];\n              const findings = [...high.map((i) => ({ title: String(i.title || \"\").slice(0, 160), severity: \"high\" })), ...low.map((i) => ({ title: String(i.title || \"\").slice(0, 160), severity: \"low\" }))].slice(0, 20);\n              await post({ tool: \"aderyn\", commitSha: sha, runUrl: process.env.RUN_URL, result: high.length > 0 ? \"fail\" : \"pass\", summary: { counts: { high: high.length, medium: 0, low: low.length, informational: 0 }, findings } });\n            } else {\n              await post({ tool: process.env.CANHAV_ADERYN === \"1\" ? \"aderyn\" : \"slither\", commitSha: sha, runUrl: process.env.RUN_URL, result: \"error\", summary: { counts: { high: 0, medium: 0, low: 0, informational: 0 }, findings: [] } });\n            }\n            const addresses = new Set();\n            const walk = (dir) => {\n              if (!fs.existsSync(dir)) return;\n              for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n                const p = path.join(dir, e.name);\n                if (e.isDirectory()) { if (e.name === \"node_modules\" || e.name.startsWith(\".\")) continue; walk(p); }\n                else if (e.name === \"run-latest.json\" && p.includes(`${path.sep}${chainId}${path.sep}`)) {\n                  try { for (const t of JSON.parse(fs.readFileSync(p, \"utf8\")).transactions || []) if (t.transactionType === \"CREATE\" && t.contractAddress) addresses.add(String(t.contractAddress).toLowerCase()); } catch {}\n                }\n              }\n            };\n            walk(process.cwd());\n            if (addresses.size) {\n              const list = [...addresses].slice(0, 100);\n              const r = await fetch(`https://sourcify.dev/server/check-all-by-addresses?addresses=${list.join(\",\")}&chainIds=${chainId}`);\n              const rows = r.ok ? await r.json() : [];\n              const verified = {};\n              for (const a of list) verified[a] = \"none\";\n              for (const row of rows) { const m = (row.chainIds || []).find((c) => String(c.chainId) === String(chainId)); if (m) verified[String(row.address).toLowerCase()] = m.status === \"perfect\" ? \"full\" : m.status ? \"partial\" : \"none\"; }\n              const all = list.every((a) => verified[a] !== \"none\");\n              await post({ tool: \"sourcify\", commitSha: sha, runUrl: process.env.RUN_URL, result: all ? \"pass\" : \"fail\", summary: { chainId, verified } });\n            }\n          })();\n          JS\n", // copy-ok, generated YAML
} as const;

export type WorkflowName = keyof typeof WORKFLOW_TEMPLATES;

export function isWorkflowName(value: unknown): value is WorkflowName {
  return typeof value === "string" && value in WORKFLOW_TEMPLATES;
}
